:root{color-scheme:dark;--background:#000;--foreground:#eee;--muted-foreground:#999}*{box-sizing:border-box}body{margin:0;padding:24px;background:#000;color:#eee;font:16px/1.5 Arial,Helvetica,sans-serif}button{font:inherit;cursor:pointer}.viz-controls{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:24px}.btn{color:#bbb;background:#141414;border:1px solid #333;border-radius:6px;min-height:44px;padding:9px 14px;text-align:left}.btn[aria-pressed=true]{color:#fff;border-color:#ddd;background:#262626}.btn-block{width:100%}.text-small{font-size:14px}.text-muted{color:#999}:focus-visible{outline:2px solid #fff;outline-offset:3px}[hidden]{display:none!important}h3{font-size:18px;font-weight:500}figcaption{font-size:16px}canvas{max-width:100%}@media(max-width:520px){body{padding:16px}}:root,.dark{color-scheme:dark;--background:#000;--foreground:#eee;--card:#000;--card-foreground:#eee;--primary:#eee;--primary-foreground:#000;--muted:#161616;--muted-foreground:#888;--border:#252525;--ring:#e5e5e5}
*{box-sizing:border-box}html,body{margin:0;background:var(--background);color:var(--foreground);font-family:Arial,Helvetica,sans-serif}
main{max-width:1120px;margin:auto;padding:32px 40px 40px}
header{display:flex;align-items:center;gap:24px;flex-wrap:wrap;margin-bottom:32px}
h1{margin:0;font-size:16px;font-weight:500;letter-spacing:-.02em}h1 span{color:#888;font-weight:400}
header p{margin:0 0 0 auto;color:#888;font-size:12px}
.controls{display:flex;gap:6px;flex-wrap:wrap}.controls button{font:inherit;font-size:14px;color:#999;border:1px solid #292929;background:#000;border-radius:5px;padding:8px 12px;cursor:pointer;min-height:44px}
.controls button[aria-pressed=true]{color:#fff;border-color:#777}.controls button:focus-visible{outline:2px solid #fff;outline-offset:3px}
.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:48px;row-gap:72px}
.study{min-width:0;padding:12px 0}.drawing{height:120px;display:flex;align-items:center}canvas{display:block;width:100%;height:44px}
h2{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:14px;font-weight:400;color:#a0a0a0;margin:14px 0 0;line-height:1.5}h2 span{color:#777;margin-right:8px}
[hidden]{display:none!important}
@media(max-width:1000px){main{padding:24px}.gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 32px}}
@media(max-width:720px){.gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}header{gap:16px}header p{margin:0}}
@media(max-width:450px){main{padding:20px}.gallery{grid-template-columns:1fr}header{margin-bottom:24px}.drawing{height:64px}}

.debug{position:relative;font-size:14px}.debug summary{cursor:pointer;padding:12px 0}
.debug fieldset{position:absolute;z-index:10;top:40px;right:0;min-width:230px;margin:0;padding:16px;background:#000;border:1px solid #525252}
.debug legend{color:#8f8f8f;padding:0 4px}.debug button{background:#000;color:#fff;border:1px solid #525252;padding:10px;min-height:44px;cursor:pointer}
.debug button[aria-pressed=true]{border-color:#fff}.debug fieldset p{margin:12px 0 0}

/* The additional matrix studies stay stacked at the same optical scale. */
.matrix-gallery{display:grid;grid-template-columns:minmax(0,1fr);max-width:496px;margin:72px auto 0;gap:40px}
@media(max-width:450px){.matrix-gallery{margin-top:40px;gap:24px}}

.twitter-export{width:100vw;min-height:100svh;max-width:none;margin:0;padding:0;display:grid;place-items:center;background:#000;overflow:hidden}
.twitter-square{width:min(100vw,100svh);aspect-ratio:1;background:#000;overflow:hidden}
.twitter-square canvas{display:block;width:100%;height:100%}
